import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Terminal & Linux — The Unix Toolbox","description":"WSL2, shell scripting, SSH, systemd and the Unix toolbox — the environment where all my work actually happens.","frontmatter":{"title":"Terminal & Linux — The Unix Toolbox","description":"WSL2, shell scripting, SSH, systemd and the Unix toolbox — the environment where all my work actually happens."},"headers":[],"relativePath":"en/skills/terminal/index.md","filePath":"en/skills/terminal/index.md"}`),a={name:`en/skills/terminal/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="terminal-linux-—-the-unix-toolbox" tabindex="-1">Terminal &amp; Linux — The Unix Toolbox <a class="header-anchor" href="#terminal-linux-—-the-unix-toolbox" aria-label="Permalink to “Terminal &amp; Linux — The Unix Toolbox”">​</a></h1><p>My primary work environment is a terminal — usually WSL2 on Windows giving me both worlds, or a bare Linux box for services. Fluency here is not nostalgia; it is leverage. Every tool I use, including every agent, ultimately drives the same Unix primitives.</p><h2 id="daily-drivers" tabindex="-1">Daily drivers <a class="header-anchor" href="#daily-drivers" aria-label="Permalink to “Daily drivers”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Tools</th></tr></thead><tbody><tr><td>Shell</td><td>bash/zsh, pipes, jq, awk/sed one-liners, fzf</td></tr><tr><td>Remote</td><td>SSH keys and agents, tmux sessions, port forwarding</td></tr><tr><td>Services</td><td>systemd units, cron, log rotation</td></tr><tr><td>Containers</td><td>Docker, compose, minimal images</td></tr><tr><td>Inspection</td><td>htop, ss/netstat, strace, journalctl</td></tr></tbody></table><p>This is also where my <a href="/Usf/en/projects/netpilot/">NetPilot</a> philosophy came from: the best terminal tools do one job, stay fast, and compose. I hold my own tools — and my agents&#39; output — to the same standard. A command that cannot be piped is a command I will rewrite.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};